def enrich(lessons):
    for lesson in lessons:
        guide = GUIDES.get(lesson['id'])
        if guide:
            lesson['theory_detail'] = guide
            for index, extras in GUIDE_EXTRAS.get(lesson['id'], {}).items():
                lesson['theory_detail'][index].update(extras)
            lesson['theory_links'] = GUIDE_LINKS.get(lesson['id'], [])
            lesson['quality']['stage_2_2'] = 'Авторская подробная теория добавлена; самостоятельная проверка Codex не является независимой лингвистической экспертизой.'
        # Enrich dictionary entries without replacing legacy string meanings.
        lesson['vocabulary_detail'] = lesson.get('vocabulary_detail', {})
        for word, meaning in lesson.get('vocabulary', {}).items():
            if word not in lesson['vocabulary_detail']:
                lesson['vocabulary_detail'][word] = {
                    'meaning_ru': meaning,
                    'example': next((e.get('correct') for e in lesson.get('examples', []) if word.casefold() in e.get('correct', '').casefold()), ''),
                    'ipa': '', 'part_of_speech': '', 'forms': '', 'stress': '',
                }
